template.script:

// Script completamente independiente - sin dependencias Odoo
(function() {
  'use strict';

  // Evitar ejecución múltiple
  if (window.favoritesLoaded) return;
  window.favoritesLoaded = true;

  console.log('🎯 Cargando favoritos...');

  function initFavorites() {
    // Buscar elementos de productos de diferentes maneras
    let productSelectors = [
      '[data-oe-model="product.template"]',
      '.oe_product',
      '[data-product-template-id]',
      '.o_wsale_product_grid_wrapper [itemscope]'
    ];

    let productItems = [];
    productSelectors.forEach(selector => {
      const items = document.querySelectorAll(selector + ':not(.favorite-processed)');
      productItems = productItems.concat(Array.from(items));
    });

    // Eliminar duplicados para evitar procesar el mismo producto varias veces
    productItems = [...new Set(productItems)];

    console.log('📦 Productos encontrados:', productItems.length);

    const productData = productItems.map(item => {
        let productId = item.getAttribute('data-oe-id') ||
                        item.getAttribute('data-product-template-id') ||
                        item.getAttribute('data-product-id');
        if (!productId) {
            const productLink = item.querySelector('a[href*="/shop/product/"]');
            if (productLink) {
                const match = productLink.href.match(/\/shop\/product\/(\d+)/);
                if (match) productId = match[1];
            }
        }
        return { item, productId: parseInt(productId) };
    }).filter(p => p.productId);

    const productIds = productData.map(p => p.productId);
    if (productIds.length === 0) {
        console.log('🎉 No se encontraron productos para procesar.');
        return;
    }

    // Obtener CSRF token si existe
    const csrfToken = document.querySelector('meta[name="csrf-token"]');
    const headers = { 'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest' };
    if (csrfToken) { headers['X-CSRFToken'] = csrfToken.getAttribute('content'); }

    // 1. Obtener el estado inicial de todos los productos
    fetch('/shop/favorites/status', {
        method: 'POST',
        headers: headers,
        body: JSON.stringify({ params: { product_ids: productIds } })
    })
    .then(response => response.ok ? response.json() : Promise.reject('Error fetching status'))
    .then(data => {
        const favoritesStatus = data.result || {};
        console.log('ℹ️ Estado inicial de favoritos:', favoritesStatus);

        // 2. Procesar y crear cada botón con su estado correcto
        productData.forEach(({ item, productId }, index) => {
            if (item.querySelector('.favorite-btn')) return; // Ya procesado
            if (document.querySelector(`.favorite-btn[data-product-id="${productId}"]`)) return;
            item.classList.add('favorite-processed');

            const isFavorited = favoritesStatus[productId] === true;

            const favoriteBtn = document.createElement('button');
            favoriteBtn.className = 'favorite-btn';
            favoriteBtn.setAttribute('data-product-id', productId);

            // Estilos
            Object.assign(favoriteBtn.style, {
                position: 'absolute', top: '8px', right: '8px', zIndex: '1000',
                background: 'rgba(255,255,255,0.95)', border: '1px solid #dc3545',
                borderRadius: '50%', width: '32px', height: '32px', fontSize: '16px',
                cursor: 'pointer', display: 'flex', alignItems: 'center',
                justifyContent: 'center', transition: 'all 0.2s', color: '#dc3545'
            });

            // Función para actualizar la UI del botón
            const updateButtonUI = (isFav) => {
                if (isFav) {
                    favoriteBtn.innerHTML = '♥';
                    favoriteBtn.title = 'Quitar de favoritos';
                    favoriteBtn.style.background = 'rgba(220,53,69,0.1)';
                } else {
                    favoriteBtn.innerHTML = '♡';
                    favoriteBtn.title = 'Marcar como favorito';
                    favoriteBtn.style.background = 'rgba(255,255,255,0.95)';
                }
            };

            updateButtonUI(isFavorited); // Establecer estado inicial

            if (getComputedStyle(item).position === 'static') {
                item.style.position = 'relative';
            }
            item.appendChild(favoriteBtn);

            // Evento click
            favoriteBtn.addEventListener('click', function(e) {
                e.preventDefault(); e.stopPropagation();
                this.disabled = true; this.style.opacity = '0.6';

                fetch('/shop/favorite/toggle', {
                    method: 'POST', headers: headers,
                    body: JSON.stringify({ params: { product_id: productId } })
                })
                .then(response => response.ok ? response.json() : Promise.reject(response))
                .then(data => {
                    if (data.result) {
                        updateButtonUI(data.result.favorited);
                    }
                })
                .catch(error => {
                    console.error('❌ Error al cambiar favorito:', error);
                    if (error.status === 401 || error.status === 403) {
                        if (confirm('Debes iniciar sesión para usar favoritos. ¿Ir al login?')) {
                            window.location.href = '/web/login?redirect=' + encodeURIComponent(window.location.pathname);
                        }
                    }
                })
                .finally(() => {
                    this.disabled = false; this.style.opacity = '1';
                });
            });
        });
        console.log('🎉 Favoritos inicializados correctamente');
    })
    .catch(error => {
        console.error('❌ Error al inicializar favoritos:', error);
    });
  }

  // Ejecutar cuando el DOM esté listo
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initFavorites);
  } else {
    // DOM ya está listo
    setTimeout(initFavorites, 100);
  }

})();
